import{_ as a,c as r,o as i,av as n}from"./chunks/framework.AOtbozFj.js";const o="/simast/assets/login_page_2.B9C7cQ_u.png",s="/simast/assets/register_partner.BmsZWfHk.png",l="/simast/assets/signin_partner_00.JdqHxkm2.png",c="/simast/assets/signin_partner_01.Be2viDDo.png",g="/simast/assets/page_gestion.BTvclWnq.png",p="/simast/assets/register_app.XGX4JBO5.png",t="/simast/assets/webhook_secret.CzO1UHZC.png",d="/simast/assets/generate_secret.BFUdBQlx.png",h="/simast/assets/generated.CXIp9KqK.png",w=JSON.parse('{"title":"Partner Onboarding","description":"","frontmatter":{},"headers":[],"relativePath":"pages/partner_onboarding.md","filePath":"pages/partner_onboarding.md"}'),u={name:"pages/partner_onboarding.md"};function m(b,e,f,S,y,v){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="partner-onboarding" tabindex="-1">Partner Onboarding <a class="header-anchor" href="#partner-onboarding" aria-label="Permalink to &quot;Partner Onboarding&quot;">​</a></h1><h2 id="_1-creating-a-simast-account-partner-onboarding" tabindex="-1">1. Creating a SIMAST Account (Partner Onboarding) <a class="header-anchor" href="#_1-creating-a-simast-account-partner-onboarding" aria-label="Permalink to &quot;1. Creating a SIMAST Account (Partner Onboarding)&quot;">​</a></h2><p>To register an application that will interact with the SIMAST API, the organization that owns the application must first be onboarded as a <strong>Partner</strong> in the MAST information system. This onboarding typically consists of submitting a <strong>Partner account request</strong> and/or creating the <strong>Partner owner account</strong> in the MAST system.</p><p>The Partner account is not immediately active. It must go through a controlled validation flow:</p><ul><li><strong>MAST Validation:</strong> The Partner account request is reviewed and validated by MAST.</li><li><strong>SIMAST Activation:</strong> Once validated, the SIMAST team activates the Partner account so it can be used to register applications and access the API.</li></ul><p>This process ensures that only verified partners can create applications, obtain credentials, and consume SIMAST services under an auditable and approved access model.</p><h3 id="steps-ui-flow" tabindex="-1">Steps (UI Flow) <a class="header-anchor" href="#steps-ui-flow" aria-label="Permalink to &quot;Steps (UI Flow)&quot;">​</a></h3><ol><li>Open the MAST portal and navigate to the Partner onboarding or registration section.</li></ol><p><a href="https://sharing.staging.simast.info/#/" target="_blank" rel="noreferrer">https://sharing.test.simast.info</a></p><p><img src="'+o+'" alt="Login Page"></p><ol start="2"><li>Submit the Partner account request (or create the Partner owner account if the process is internal).</li></ol><p><img src="'+s+'" alt="Register Partner"></p><ol start="3"><li>Wait for MAST validation.</li><li>After validation, the SIMAST team activates the account.</li></ol><h2 id="_2-registering-the-application" tabindex="-1">2. Registering the Application <a class="header-anchor" href="#_2-registering-the-application" aria-label="Permalink to &quot;2. Registering the Application&quot;">​</a></h2><p>After your Partner account has been <strong>validated by MAST</strong> and <strong>activated by the SIMAST team</strong>, you must complete the initial security step: <strong>first login and mandatory password change</strong>.</p><p>Once your account is fully operational, you can register your application in SIMAST by using the <strong>API Manager</strong> (French UI label: <strong>&quot;Gestionnaire API&quot;</strong>). Registering an application is required in order to generate the credentials and configuration needed for API access.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Partner account request validated by MAST</li><li>Partner account activated by the SIMAST team</li><li>First login completed</li><li>Initial password changed successfully</li></ul><h3 id="steps-ui-flow-1" tabindex="-1">Steps (UI Flow) <a class="header-anchor" href="#steps-ui-flow-1" aria-label="Permalink to &quot;Steps (UI Flow)&quot;">​</a></h3><ol><li><p>Sign in to the SIMAST portal with your Partner owner account.</p><p><img src="'+l+'" alt="Click Portal Partner"></p><p><img src="'+c+'" alt="Sign In"></p></li><li><p>Complete the <strong>First Login Password Change</strong> (if prompted).</p></li><li><p>From the main navigation, open <strong>API Manager</strong> (<strong>&quot;Gestionnaire API&quot;</strong>).</p></li></ol><p><img src="'+g+'" alt="Api Management Page"></p><ol start="4"><li>Select <strong>Register Application</strong> (or equivalent action) to create a new application entry.</li><li>Fill in the application details (e.g., name, description, callback URL if applicable).</li></ol><p><img src="'+p+'" alt="Register App"></p><ol start="6"><li>Save to complete the registration.</li></ol><p><img src="'+t+'" alt="WebHook Secret"></p><p>Right after the application is created, SIMAST generates its <strong><code>webhook_secret</code></strong> — used to sign both the webhook notifications (<code>demande.completed</code>/<code>demande.failed</code>) and the return URL calls described in <a href="/simast/pages/return_url.html">Return URL</a> — and displays it <strong>exactly once</strong>, in the confirmation dialog shown above.</p><ul><li>Copy and store the secret immediately in a secure password manager or secrets vault.</li><li>Once you close this dialog, the secret is never shown again in clear text.</li><li>If the secret is lost, it must be regenerated (see section 4 below) — SIMAST cannot retrieve a lost secret.</li></ul><p>The dialog also reminds you how the secret is used to verify signatures — see <a href="/simast/pages/return_url.html#verifying-the-webhook-signature">Verifying the webhook signature</a> for the full explanation.</p><h2 id="validation-and-activation-rules-agreement-based" tabindex="-1">Validation and Activation Rules (Agreement-Based) <a class="header-anchor" href="#validation-and-activation-rules-agreement-based" aria-label="Permalink to &quot;Validation and Activation Rules (Agreement-Based)&quot;">​</a></h2><p>If a formal <strong>agreement</strong> has already been signed between <strong>MAST</strong> and the Partner during the Partner account creation process, the application will be <strong>automatically validated and activated</strong> once it is registered.</p><p>If no agreement exists at the time of registration, the application will remain <strong>pending</strong> until one of the following conditions is met:</p><ul><li>A signed agreement is concluded between MAST and the operating Partner; or</li><li>MAST grants an <strong>exceptional authorization</strong>, which is then communicated to the SIMAST team for activation.</li></ul><p>In all cases, application activation remains subject to MAST’s governance and SIMAST’s operational enforcement of access controls.</p><h2 id="_3-public-keys-client-secrets" tabindex="-1">3. Public Keys &amp; Client Secrets <a class="header-anchor" href="#_3-public-keys-client-secrets" aria-label="Permalink to &quot;3. Public Keys &amp; Client Secrets&quot;">​</a></h2><p>SIMAST allows an application to have <strong>multiple public keys and client secrets</strong>. This enables key rotation, parallel environments (e.g., staging vs. production), and controlled credential lifecycle management.</p><p>However, SIMAST reserves the right—at its sole discretion—to <strong>revoke any key or secret without prior notice</strong>, particularly in cases of suspected misuse, security incidents, policy violations, or governance requirements.</p><h3 id="generating-a-public-key-and-client-secret" tabindex="-1">Generating a Public Key and Client Secret <a class="header-anchor" href="#generating-a-public-key-and-client-secret" aria-label="Permalink to &quot;Generating a Public Key and Client Secret&quot;">​</a></h3><p>To generate the <strong>public key</strong> and <strong>client secret</strong> required to obtain an application access token, navigate to the credentials section (Generate Secret - Generer Secret) from the <strong>API Manager</strong>.</p><p><img src="'+d+'" alt="Generate Secret"></p><p><img src="'+h+'" alt="Generated Secret"></p><h3 id="important-security-note-one-time-secret-display" tabindex="-1">Important Security Note (One-Time Secret Display) <a class="header-anchor" href="#important-security-note-one-time-secret-display" aria-label="Permalink to &quot;Important Security Note (One-Time Secret Display)&quot;">​</a></h3><p>The <strong>client secret is displayed only once</strong>, at the time it is created. After you leave the creation screen, it will not be shown again.</p><ul><li>Save the client secret immediately.</li><li>Store it in a secure password manager or secrets vault (recommended).</li><li>If the secret is lost or exposed, generate a new one and revoke the compromised credential.</li></ul><h2 id="_4-webhook-secret-rotation" tabindex="-1">4. Webhook Secret Rotation <a class="header-anchor" href="#_4-webhook-secret-rotation" aria-label="Permalink to &quot;4. Webhook Secret Rotation&quot;">​</a></h2><p>Like the client secret, the <strong><code>webhook_secret</code></strong> can be rotated at any time from the <strong>API Manager</strong>, without waiting for it to be compromised — for example as part of a routine security policy, or immediately after a suspected leak.</p><p><img src="'+t+'" alt="WebHook Secret Regenerate"></p><h3 id="regenerating-the-secret" tabindex="-1">Regenerating the Secret <a class="header-anchor" href="#regenerating-the-secret" aria-label="Permalink to &quot;Regenerating the Secret&quot;">​</a></h3><ol><li>From the <strong>API Manager</strong>, locate the application and select <strong>Regenerate</strong> (Webhook Secret).</li><li>Confirm the action — regeneration is immediate and cannot be undone.</li><li>The new secret is displayed <strong>once</strong>, in the same confirmation dialog shown at registration above — copy it immediately.</li></ol><h3 id="grace-period-for-the-previous-secret" tabindex="-1">Grace Period for the Previous Secret <a class="header-anchor" href="#grace-period-for-the-previous-secret" aria-label="Permalink to &quot;Grace Period for the Previous Secret&quot;">​</a></h3><p>To avoid breaking signature verification on the third-party side during the switch-over, the <strong>previous secret stays valid for 24 hours</strong> after regeneration:</p><ul><li>Both the current and the previous secret are accepted for verifying webhook signatures (<code>X-Webhook-Signature</code>) and return URL signatures during this window.</li><li>After 24 hours, only the new secret is accepted — verification with the old secret will fail.</li><li>Use this window to update your stored secret and confirm your signature verification logic works with the new value before the old one expires.</li></ul><blockquote><p><strong>Recommendation:</strong> Treat every regeneration like a full secret change — update your configuration immediately rather than relying on the 24h grace period as a normal operating mode.</p></blockquote><p>See <a href="/simast/pages/return_url.html#verifying-the-webhook-signature">Verifying the webhook signature</a> for the signature verification logic, which already accounts for this rotation window.</p>',53)])])}const P=a(u,[["render",m]]);export{w as __pageData,P as default};
